<script lang="ts">
 import { onMount } from 'svelte';
 import { Button } from '@hasbai/ui/button';
 import { Input } from '@hasbai/ui/input';
 import { Textarea } from '@hasbai/ui/textarea';
 import { Notice } from '@hasbai/ui/notice';
 import * as Dialog from '@hasbai/ui/dialog';
 import { Plus, Pencil, Trash2, Network, History } from '@lucide/svelte';
 import { trackLoading } from '@hasbai/ui/progress';
 import ModelPicker from './ModelPicker.svelte';
 import type { Model } from './catalog';
 import type { Api } from './lib';
 type Route={id:string;name:string;elements?:{id:string;type:string;properties?:{model?:string;provider?:string}}[];deployment?:{version_id:string}};
 type Version={version_id:string;created_at?:string;is_valid?:boolean};
 let {api,onchanged}:{api:Api;onchanged:()=>void}=$props();
 let routeDialog=$state<HTMLElement|null>(null);
 let routes=$state<Route[]>([]),error=$state(''),busy=$state(false),loading=$state(true),editing=$state(false),name=$state(''),id=$state(''),draft=$state(''),versions=$state<Version[]>([]),history=$state<Route>(),remove=$state<Route>();
 type ModelNode={id:string;type:string;properties:{provider:string;model:string;timeout:number;retries:number};outputs:Record<string,{elementId:string}>};
 let models=$state<Model[]>([]);
 let modelNodes=$derived.by(()=>{try{const rows=JSON.parse(draft);return (Array.isArray(rows)?rows:[]).filter((row):row is ModelNode=>row?.type==='model'&&row.properties);}catch{return [];}});
 function changeNode(nodeId:string,values:Partial<ModelNode['properties']>){try{const rows=JSON.parse(draft);draft=JSON.stringify(rows.map((row:ModelNode)=>row.id===nodeId?{...row,properties:{...row.properties,...values}}:row),null,2);}catch{error='请先修正路由 JSON';}}
 function chooseNode(nodeId:string,value:string){const slash=value.indexOf('/');changeNode(nodeId,{provider:value.slice(0,slash),model:value.slice(slash+1)});}
 async function loadModels(){try{models=((await (await api('/v1/models')).json()) as {data:Model[]}).data.filter(m=>m.type==='chat'&&m.id.startsWith('custom-'));}catch{models=[];}}
 const base='/api/admin/gateways/default/routes';
 trackLoading(()=>loading||busy);
 onMount(()=>{void load();void loadModels();});
 async function load(){loading=true;error='';try{routes=((await (await api(base)).json()) as {result:Route[]}).result??[];}catch(e){error=(e as Error).message;}finally{loading=false;}}
 function edit(route?:Route){id=route?.id??'';name=route?.name??'';error='';draft=JSON.stringify(route?.elements??[{id:'start',type:'start',outputs:{next:{elementId:'model'}}},{id:'model',type:'model',properties:{provider:'',model:'',timeout:60000,retries:0},outputs:{success:{elementId:'end'},fallback:{elementId:'end'}}},{id:'end',type:'end',outputs:{}}],null,2);editing=true;}
 async function save(){busy=true;error='';try{let elements;try{elements=JSON.parse(draft);}catch{throw Error('路由规则不是有效 JSON');}if(!Array.isArray(elements))throw Error('路由规则必须是节点数组');
  if(id){await api(base+'/'+id+'/versions','POST',{elements});}
  else{const value=(await (await api(base,'POST',{name,elements})).json()) as {result:Route};id=value.result.id;}
  editing=false;await load();await showHistory(routes.find(r=>r.id===id)??{id,name});
 }catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function deploy(routeId:string,version:string){busy=true;error='';try{await api(base+'/'+routeId+'/deployments','POST',{version_id:version});editing=false;history=undefined;await load();onchanged();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function showHistory(route:Route){history=route;versions=[];busy=true;error='';try{versions=((await (await api(base+'/'+route.id+'/versions')).json()) as {result:Version[]}).result??[];}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function destroy(){if(!remove)return;busy=true;error='';try{await api(base+'/'+remove.id,'DELETE');remove=undefined;await load();onchanged();}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="management-heading"><div><h1>动态路由</h1><p>管理模型分流规则与部署版本</p></div><Button onclick={()=>edit()} disabled={busy}><Plus size={16}/>创建路由</Button></div>
{#if error&&!editing&&!history&&!remove}<Notice variant="error">{error}<Button variant="outline" onclick={load}>重试</Button></Notice>{/if}
{#if loading}<div class="route-skeleton" aria-label="正在加载路由"></div>{:else if !routes.length}<div class="catalog-empty"><Network size={30}/><h2>尚无动态路由</h2><Button variant="outline" onclick={()=>edit()}>创建路由</Button></div>{:else}<div class="route-grid">{#each routes as route(route.id)}<article class="route-card"><header><span class="provider-avatar"><Network size={18}/></span><span class="pill">{route.deployment?'已部署':'未部署'}</span></header><h2>{route.name}</h2><code>dynamic/{route.name}</code><div class="route-flow">{#each route.elements?.filter(e=>e.type==='model')??[] as node,i}<span>{node.properties?.model}</span>{:else}<span>自定义路由规则</span>{/each}</div>{#if route.deployment}<p class="version-id">当前版本 {route.deployment.version_id}</p>{/if}<footer><Button variant="outline" onclick={()=>edit(route)}><Pencil size={14}/>编辑规则</Button><Button variant="ghost" onclick={()=>showHistory(route)}><History size={15}/>版本</Button><Button variant="ghost" aria-label={'删除路由 '+route.name} onclick={()=>remove=route}><Trash2 size={15}/></Button></footer></article>{/each}</div>{/if}
<Dialog.Root bind:open={editing}><Dialog.Content class="route-dialog" bind:ref={routeDialog} onOpenAutoFocus={e=>{e.preventDefault();routeDialog?.focus({preventScroll:true});}}><Dialog.Header><Dialog.Title>{id?'编辑路由规则':'创建动态路由'}</Dialog.Title><Dialog.Description>保存生成新版本，发布后才会用于对话。条件、分流、限流与回退节点均保留。</Dialog.Description></Dialog.Header><form class="config-form" onsubmit={e=>{e.preventDefault();void save();}}><label for="route-name">路由名称</label><Input id="route-name" bind:value={name} required pattern="[a-zA-Z0-9_-]+" disabled={!!id||busy}/><div class="route-model-fields">{#each modelNodes as node (node.id)}<section><header><h3>模型 · {node.id}</h3><ModelPicker {models} bind:value={()=>node.properties.provider+'/'+node.properties.model,value=>chooseNode(node.id,value)} disabled={busy}/></header><div class="node-fields"><label for={'node-provider-'+node.id}>Provider</label><Input id={'node-provider-'+node.id} value={node.properties.provider} oninput={e=>changeNode(node.id,{provider:e.currentTarget.value})} disabled={busy} required/><label for={'node-model-'+node.id}>模型 ID</label><Input id={'node-model-'+node.id} value={node.properties.model} oninput={e=>changeNode(node.id,{model:e.currentTarget.value})} disabled={busy} required/><label for={'node-timeout-'+node.id}>超时（毫秒）</label><Input id={'node-timeout-'+node.id} type="number" min="0" value={node.properties.timeout} oninput={e=>changeNode(node.id,{timeout:Number(e.currentTarget.value)})} disabled={busy}/><label for={'node-retries-'+node.id}>重试次数</label><Input id={'node-retries-'+node.id} type="number" min="0" step="1" value={node.properties.retries} oninput={e=>changeNode(node.id,{retries:Number(e.currentTarget.value)})} disabled={busy}/></div></section>{/each}</div><details class="advanced-route"><summary>高级路由规则 · JSON</summary><label for="route-elements">路由节点 · JSON</label><Textarea id="route-elements" class="graph-editor" bind:value={draft} rows={15} disabled={busy} required/><p class="muted">支持条件、分流、限流和回退；outputs 连接节点 ID。</p></details>{#if error}<Notice variant="error">{error}</Notice>{/if}<div class="route-save"><Button type="submit" disabled={busy}>{busy?'保存中…':'保存版本'}</Button></div></form></Dialog.Content></Dialog.Root>
<Dialog.Root open={!!history} onOpenChange={open=>{if(!open&&!busy)history=undefined;}}><Dialog.Content><Dialog.Header><Dialog.Title>{history?.name} · 版本</Dialog.Title><Dialog.Description>发布旧版本可回滚路由规则。</Dialog.Description></Dialog.Header>{#if error}<Notice variant="error">{error}</Notice>{/if}<div class="version-list">{#each versions as version}<article><div><code>{version.version_id}</code><p>{version.created_at?new Date(version.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):''}</p></div><Button variant="outline" disabled={busy||version.is_valid===false||history?.deployment?.version_id===version.version_id} onclick={()=>history&&deploy(history.id,version.version_id)}>{history?.deployment?.version_id===version.version_id?'当前版本':'发布'}</Button></article>{:else}<p>{busy?'正在读取版本…':'没有可用版本'}</p>{/each}</div></Dialog.Content></Dialog.Root>
<Dialog.Root open={!!remove} onOpenChange={open=>{if(!open&&!busy)remove=undefined;}}><Dialog.Content><Dialog.Header><Dialog.Title>删除路由 {remove?.name}？</Dialog.Title><Dialog.Description>使用此路由的请求将无法继续。</Dialog.Description></Dialog.Header>{#if error}<Notice variant="error">{error}</Notice>{/if}<Dialog.Footer><Button variant="outline" disabled={busy} onclick={()=>remove=undefined}>取消</Button><Button variant="destructive" disabled={busy} onclick={destroy}>删除路由</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
